1	import {WebSocket} from 'ws';
2	import type {SessionEntry} from '../../types/session.js';
3	import type {ChatSession} from '../../types/session.js';
4	import {ErrorCodes} from '../../types/messages.js';
5	import type {ListSessionsMessage, OutgoingMessage, SessionSummaryFrame} from '../../types/messages.js';
6	import type {SessionStore, SessionSummary} from '../../types/sessionStore.js';
7	import {ThinkingTagParser, ParsedSegment} from '../../infrastructure/parsers/thinkingTagParser.js';
8	import {validateMessage} from './validation.js';
9	import type {ValidationResult} from './validation.js';
10	import {PerSessionLock} from '../../shared/perSessionLock.js';
11	import type {ChatOrchestrator} from '../../orchestration/chatOrchestrator.js';
12	import {AIError} from '../../types/ai.js';
13	import type {MessageChunk} from '../../types/ai.js';
14	import {
15	  createUserEntry,
16	  createAssistantEntry,
17	  createThinkingEntry,
18	  createToolEntry,
19	} from '../../orchestration/entryFactories.js';
20	import {appendEntry, appendDelta, commitEntry, markTruncated} from '../../orchestration/entryMutations.js';
21	import {
22	  sendJson,
23	  sendUpsert,
24	  sendDelta,
25	  sendCommit,
26	  sendSkip,
27	  sendError,
28	  sendSessionList,
29	  sendStreamEnd,
30	} from './sender.js';
31	import {log} from '../../shared/logger.js';
32	
33	interface StreamState {
34	  thinkingIndex: number | null;
35	  assistantIndex: number | null;
36	  suppressOutput: boolean;
37	  sentAssistantIndices: number[];
38	}
39	
40	type StateIndexKey = 'thinkingIndex' | 'assistantIndex';
41	type EntryFactory = typeof createThinkingEntry | typeof createAssistantEntry;
42	export function createMessageHandler(orchestrator: ChatOrchestrator, sessionStore?: SessionStore) {
43	  // Keyed by session, not socket: a resumed session can be open on more than one (specs/hal-engine-architecture/spec.md).
44	  const lock = new PerSessionLock();
45	  // Per socket, so answers to its frames are written in the order it asked, whatever each answer waits on.
46	  const answers = new WeakMap<WebSocket, Promise<void>>();
47	  return function handleMessage(
48	    ws: WebSocket,
49	    session: ChatSession,
50	    rawMessage: unknown,
51	    signal?: AbortSignal
52	  ): Promise<void> {
53	    const validation = validateMessage(rawMessage);
54	    // Queued with no await before it, so a session's user_messages, a failed one too, are answered in arrival order.
55	    if (isUserMessageFrame(rawMessage)) {
56	      return lock.run(session.sessionId, () =>
57	        answerInTurn(ws, session, orchestrator, validation, sessionStore, signal)
58	      );
59	    }
60	    // The chain never rejects (wsErrorHandler answers a throw), so a fulfilled ahead always runs this answer.
61	    const answered = (answers.get(ws) ?? Promise.resolve()).then(() =>
62	      wsErrorHandler(ws, async () => answerFrame(ws, session, validation, sessionStore))
63	    );
64	    answers.set(ws, answered);
65	    return answered;
66	  };
67	}
68	
69	// The whole answer, an error and the stream_end included, goes out inside the lock: an error frame names no message.
70	async function answerInTurn(
71	  ws: WebSocket,
72	  session: ChatSession,
73	  orchestrator: ChatOrchestrator,
74	  validation: ValidationResult,
75	  sessionStore: SessionStore | undefined,
76	  signal: AbortSignal | undefined
77	): Promise<void> {
78	  // Its socket closed while it waited: nobody is left to read the answer, and a session's last close took its credentials.
79	  if (signal?.aborted || ws.readyState === WebSocket.CLOSING || ws.readyState === WebSocket.CLOSED) {
80	    log.info('message', 'queued message dropped: its socket closed', {sessionId: session.sessionId});
81	    return;
82	  }
83	  const startedAt = Date.now();
84	  try {
85	    await wsErrorHandler(ws, () => answerUserMessage(ws, session, orchestrator, validation, sessionStore, signal));
86	  } finally {
87	    endTurn(ws, session, signal, startedAt);
88	  }
89	}
90	
91	// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
92	function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
93	  if (signal?.aborted) {
94	    log.info('message', 'turn abandoned: its socket closed', {
95	      sessionId: session.sessionId,
96	      elapsedMs: Date.now() - startedAt,
97	    });
98	    return;
99	  }
100	  sendStreamEnd(ws);
101	}
102	
103	async function answerUserMessage(
104	  ws: WebSocket,
105	  session: ChatSession,
106	  orchestrator: ChatOrchestrator,
107	  validation: ValidationResult,
108	  sessionStore: SessionStore | undefined,
109	  signal: AbortSignal | undefined
110	): Promise<void> {
111	  const message = validation.valid ? validation.data : undefined;
112	  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
113	  await answerFrame(ws, session, validation, sessionStore);
114	}
115	
116	async function answerFrame(
117	  ws: WebSocket,
118	  session: ChatSession,
119	  validation: ValidationResult,
120	  sessionStore: SessionStore | undefined
121	): Promise<void> {
122	  if (!validation.valid) {
123	    log.warn('message', 'validation failed', {error: validation.error});
124	    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
125	    return;
126	  }
127	
128	  const message = validation.data;
129	  if (message.type === 'ping') handlePing(ws, message.timestamp);
130	  if (message.type === 'list_sessions') await handleListSessions(ws, session, sessionStore, message);
131	}
132	
133	// Answered off the session lock: a history request is not a turn and must not queue behind a streaming answer.
134	async function handleListSessions(
135	  ws: WebSocket,
136	  session: ChatSession,
137	  sessionStore: SessionStore | undefined,
138	  message: ListSessionsMessage
139	): Promise<void> {
140	  try {
141	    // The user id is the connection's own, read from the session the upgrade authenticated — never from the frame.
142	    const summaries =
143	      (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
144	    sendSessionList(ws, summaries.map(sessionSummaryFrame));
145	  } catch (error) {
146	    // The frame names no store detail, and neither does the log name a conversation.
147	    const detail = error instanceof Error ? error.message : 'Unknown error';
148	    log.error('ws', 'conversation list failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
149	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Could not list conversations');
150	  }
151	}
152	
153	// A Date does not survive JSON.stringify as a Date, so the two times go out as ISO strings.
154	function sessionSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
155	  return {
156	    sessionId: summary.sessionId,
157	    createdAt: isoOf(summary.createdAt),
158	    updatedAt: isoOf(summary.updatedAt),
159	    entryCount: summary.entryCount,
160	  };
161	}
162	
163	function isoOf(time: Date | string | number): string {
164	  return new Date(time).toISOString();
165	}
166	
167	// Read from the raw frame, so a user_message that fails validation still gets its stream_end.
168	function isUserMessageFrame(rawMessage: unknown): boolean {
169	  return typeof rawMessage === 'object' && rawMessage !== null && Reflect.get(rawMessage, 'type') === 'user_message';
170	}
171	
172	async function wsErrorHandler(ws: WebSocket, action: () => Promise<void>): Promise<void> {
173	  try {
174	    await action();
175	  } catch (error) {
176	    const message = error instanceof Error ? error.message : 'Unknown error';
177	    const code = error instanceof AIError ? error.code : 'UNKNOWN';
178	    log.error('message', 'handling error', {error: message, code});
179	    if (error instanceof AIError && error.code === 'RATE_LIMITED') {
180	      sendError(ws, ErrorCodes.RATE_LIMITED, 'AI service is busy, please try again');
181	      return;
182	    }
183	    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
184	  }
185	}
186	
187	async function handleUserMessage(
188	  ws: WebSocket,
189	  session: ChatSession,
190	  orchestrator: ChatOrchestrator,
191	  content: string,
192	  signal: AbortSignal | undefined
193	): Promise<void> {
194	  log.info('message', 'user message received', {sessionId: session.sessionId, contentLength: content.length});
195	
196	  const userEntry = createUserEntry(content);
197	  const userIndex = appendEntry(session, userEntry);
198	  sendUpsert(ws, userIndex, userEntry);
199	
200	  const parser = new ThinkingTagParser();
201	  const state: StreamState = {
202	    thinkingIndex: null,
203	    assistantIndex: null,
204	    suppressOutput: false,
205	    sentAssistantIndices: [],
206	  };
207	
208	  let textChunkCount = 0;
209	
210	  try {
211	    for await (const chunk of orchestrator.processMessageStream(session, {signal})) {
212	      // Its socket closed: breaking returns the run's generator, so the run stops and its own teardown still runs.
213	      if (signal?.aborted) break;
214	      textChunkCount = logChunk(chunk, textChunkCount);
215	      processChunk(ws, session, state, parser, chunk);
216	    }
217	  } finally {
218	    // Anything still open here was cut short: a stop has already flushed the parser and committed every entry it opened.
219	    flushHeldText(ws, session, state, parser);
220	    closeCutOff(ws, session, state, 'thinkingIndex');
221	    closeCutOff(ws, session, state, 'assistantIndex');
222	  }
223	
224	  if (textChunkCount > 0) {
225	    log.debug('stream', `received ${textChunkCount} text chunks`);
226	  }
227	  log.info('stream', 'stream completed', {suppressed: state.suppressOutput, entries: session.entries.length});
228	}
229	
230	// Diagnostics only: counts a run of text chunks so it is logged once, not per token.
231	function logChunk(chunk: MessageChunk, textChunkCount: number): number {
232	  if (chunk.type === 'text') return textChunkCount + 1;
233	
234	  if (textChunkCount > 0) {
235	    log.debug('stream', `received ${textChunkCount} text chunks`);
236	  }
237	
238	  if (chunk.type === 'tool_result') {
239	    log.debug('stream', 'tool_result chunk', {
240	      messageCount: chunk.clientMessages.length,
241	      types: chunk.clientMessages.map(m => m.type),
242	    });
243	    return 0;
244	  }
245	
246	  log.debug('stream', 'chunk', {type: chunk.type});
247	  return 0;
248	}
249	
250	function processChunk(
251	  ws: WebSocket,
252	  session: ChatSession,
253	  state: StreamState,
254	  parser: ThinkingTagParser,
255	  chunk: MessageChunk
256	): void {
257	  if (chunk.type === 'text') return processTextChunk(ws, session, state, parser, chunk.text);
258	  if (chunk.type === 'tool_use') return processToolUseChunk(ws, session, chunk.toolCall);
259	  if (chunk.type === 'tool_result') return processToolResultChunk(ws, chunk.clientMessages);
260	  if (chunk.type === 'suppress_output') return processSuppressChunk(ws, session, state);
261	  if (chunk.type === 'stop') return processStopChunk(ws, session, state, parser);
262	}
263	
264	function processTextChunk(
265	  ws: WebSocket,
266	  session: ChatSession,
267	  state: StreamState,
268	  parser: ThinkingTagParser,
269	  text: string
270	): void {
271	  const segments = parser.push(text);
272	  for (const segment of segments) {
273	    handleTextSegment(ws, session, state, segment);
274	  }
275	}
276	
277	function handleTextSegment(ws: WebSocket, session: ChatSession, state: StreamState, segment: ParsedSegment): void {
278	  if (segment.type === 'thinking') {
279	    streamSegment(ws, session, state, 'thinkingIndex', createThinkingEntry, segment.content);
280	    return;
281	  }
282	  commitAndClear(ws, session, state, 'thinkingIndex');
283	  streamSegment(ws, session, state, 'assistantIndex', createAssistantEntry, segment.content);
284	}
285	
286	function streamSegment(
287	  ws: WebSocket,
288	  session: ChatSession,
289	  state: StreamState,
290	  key: StateIndexKey,
291	  createEntry: EntryFactory,
292	  content: string
293	): void {
294	  const isNew = initSegment(session, state, key, createEntry);
295	  if (isNew && state.suppressOutput) skipSuppressed(ws, session, state[key]!);
296	  if (isNew && !state.suppressOutput) sendUpsert(ws, state[key]!, session.entries[state[key]!]);
297	  appendDelta(session, state[key]!, content);
298	  if (!state.suppressOutput) sendDelta(ws, state[key]!, content);
299	}
300	
301	// Stored as suppressed, so a replay on resume shows the client what it saw live and not the text a tool hid.
302	function skipSuppressed(ws: WebSocket, session: ChatSession, index: number): void {
303	  markSuppressed(session, index);
304	  sendSkip(ws, index);
305	}
306	
307	function markSuppressed(session: ChatSession, index: number): void {
308	  const entry = session.entries[index];
309	  if (entry.role === 'assistant' || entry.role === 'thinking') entry.suppressed = true;
310	}
311	
312	function initSegment(session: ChatSession, state: StreamState, key: StateIndexKey, createEntry: EntryFactory): boolean {
313	  if (state[key] !== null) return false;
314	  state[key] = appendEntry(session, createEntry());
315	  return true;
316	}
317	
318	function commitAndClear(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
319	  const index = state[key];
320	  if (index === null) return;
321	
322	  commitEntry(session, index);
323	  state[key] = null;
324	
325	  // Only what the client received can be retracted, and only assistant entries.
326	  if (state.suppressOutput) return;
327	
328	  sendCommit(ws, index);
329	  if (key === 'assistantIndex') state.sentAssistantIndices.push(index);
330	}
331	
332	function processToolUseChunk(
333	  ws: WebSocket,
334	  session: ChatSession,
335	  toolCall: {name: string; input: Record<string, unknown>}
336	): void {
337	  const toolEntry = createToolEntry(toolCall.name, toolCall.input);
338	  const toolIndex = appendEntry(session, toolEntry);
339	  sendUpsert(ws, toolIndex, toolEntry);
340	}
341	
342	function processToolResultChunk(ws: WebSocket, clientMessages: OutgoingMessage[]): void {
343	  for (const msg of clientMessages) {
344	    log.debug('stream', 'forwarding client message to frontend', {
345	      type: msg.type,
346	      index: 'index' in msg ? msg.index : undefined,
347	    });
348	    sendJson(ws, msg);
349	  }
350	}
351	
352	// Retracts what the client saw: every assistant entry sent so far is re-sent blank.
353	function processSuppressChunk(ws: WebSocket, session: ChatSession, state: StreamState): void {
354	  // Closed as streamed so far: an open answer is then retracted like a sent one, and what follows opens new entries.
355	  commitOpenEntries(ws, session, state);
356	  log.debug('stream', 'suppression activated', {blankingEntries: state.sentAssistantIndices});
357	
358	  for (const idx of state.sentAssistantIndices) {
359	    sendUpsert(ws, idx, {...session.entries[idx], content: ''} as SessionEntry);
360	    markSuppressed(session, idx);
361	  }
362	
363	  state.sentAssistantIndices = [];
364	  state.suppressOutput = true;
365	}
366	
367	function processStopChunk(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
368	  flushHeldText(ws, session, state, parser);
369	  commitOpenEntries(ws, session, state);
370	}
371	
372	// The parser holds back a tail that might open a tag; without this the tail of a cut-off answer would be lost.
373	function flushHeldText(ws: WebSocket, session: ChatSession, state: StreamState, parser: ThinkingTagParser): void {
374	  for (const segment of parser.flush()) {
375	    handleTextSegment(ws, session, state, segment);
376	  }
377	}
378	
379	// The flag lives on the stored entry even when suppressed; only a visible entry is re-sent, which is how a live client learns it.
380	function closeCutOff(ws: WebSocket, session: ChatSession, state: StreamState, key: StateIndexKey): void {
381	  const index = state[key];
382	  if (index === null) return;
