18	// One line per frame; entries carry generated timestamps no assertion should read.
19	const wire = (sent: OutgoingMessage[]): string[] =>
20	  sent.map(frame => {
21	    if (frame.type === 'entry_upsert') {
22	      const content = 'content' in frame.entry ? frame.entry.content : '';
23	      return `upsert ${frame.index} ${frame.entry.role} ${JSON.stringify(content)}`;
24	    }
25	    if (frame.type === 'entry_delta') return `delta ${frame.index} ${JSON.stringify(frame.delta)}`;
26	    if (frame.type === 'entry_commit') return `commit ${frame.index}`;
27	    if (frame.type === 'entry_skip') return `skip ${frame.index}`;
28	    if (frame.type === 'error') return `error ${frame.code}`;
29	    if (frame.type === 'pong') return `pong ${frame.timestamp}`;
30	    if (frame.type === 'session_list') {
31	      const rows = frame.sessions;
32	      return `list ${rows.map(row => row.sessionId).join(',')}`;
33	    }
34	    return frame.type;
35	  });
