46	const harness = (chunks: MessageChunk[], {failWith, pauseAfter}: StreamScript = {}) => {
47	  const sent: OutgoingMessage[] = [];
48	  const ws = {send: (raw: string) => sent.push(JSON.parse(raw) as OutgoingMessage)} as unknown as WebSocket;
49	
50	  const stream = async function* (): AsyncGenerator<MessageChunk> {
51	    for (const [position, chunk] of chunks.entries()) {
52	      if (pauseAfter && position === pauseAfter.chunks) await pauseAfter.until;
53	      yield chunk;
54	    }
55	    if (failWith) throw failWith;
56	  };
57	
58	  const processMessageStream = jest.fn(stream);
59	  const orchestrator = {processMessageStream} as unknown as ChatOrchestrator;
60	  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
61	
62	  const handle = createMessageHandler(orchestrator);
63	
64	  return {
65	    session,
66	    processMessageStream,
67	    sent,
68	    frames: () => wire(sent),
69	    send: (raw: unknown = {type: 'user_message', content: 'hello'}, signal?: AbortSignal) =>
70	      handle(ws, session, raw, signal),
71	  };
72	};
